    public boolean isContactChanged() { return contactChanged; }
    /** Their tags as stored (see {@link net.officefloor.hq.app.claim.Tags}), null when they have none. */
    public String getTags() { return tags; }
    public void setTags(String tags) { this.tags = tags; }
    /** The sheet they were transferred from, null when they were not transferred here. */
    public String getOrigin() { return origin; }
    public void setOrigin(String origin) { this.origin = origin; }
    /** The sheet's today on which a transfer brought them here, null when they were not transferred here. */
    public LocalDate getArrivedOn() { return arrivedOn; }
    public void setArrivedOn(LocalDate arrivedOn) { this.arrivedOn = arrivedOn; }
    public void setVersion(long version) { this.version = version; }
    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
    /** Their past retirements (each ended by unretiring them), oldest first. */
    public List<PastRetirement> getPastRetirements() { return pastRetirements; }
    /** Their flag, null when they were never flagged (it may be past its until-date). */
    public Flag getFlag() { return flag; }
    public void setFlag(Flag flag) { this.flag = flag; }
    /** Their approver, a user who may approve or reject their PENDING claims as a steward may (null when none). */
    public String getApprover() { return approver; }
    public void setApprover(String approver) { this.approver = approver; }
    /** Whether their flag is in force on the date: only a steward may open a claim of theirs then. */
    public boolean flaggedOn(LocalDate date) { return flag != null && flag.inForceOn(date); }
    /** Their snapshots, one per SNAPSHOT written for them, oldest first. */
    public List<Snapshot> getSnapshots() { return snapshots; }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.statement.StatementSummary;

/** A person as the front end reads it: the grade in force on the sheet's today and every grade with the
 *  date (yyyy-MM-dd) it applies from (null for the first, from the beginning of time), with their
 *  statement count and the last statement's due-total and date (null when none was taken), whether they
 *  are retired and from when (null when not) and whether the sheet's today has reached that date, whether they have any hold
 *  and each hold's from-date and to-date (null for no end), the ids of their patrons (in the order named), and their own terms
 *  in force on the sheet's today (whole days, null when none), their contact (null when none) and their aliases, sorted as names are compared, and whether they clash: their
 *  name or an alias is used as a name or alias on another sheet of the sheet's tree, and the sheet they were
 *  transferred from (null when they were not), and their past retirements, oldest first, and their tags, sorted, and their snapshots, oldest first, and their statements still standing, oldest first (by date), and the reason of their flag while it is in force on the sheet's today (null when none is), and their approver (null when none). */
public record PersonResponse(long id, String name, String grade, List<GradeFrom> grades, long version,
        int statementCount, String statedTotal, String statementDate, boolean retired, String retiredFrom,
        boolean held, List<HoldFrom> holds, List<Long> patronIds, Integer terms,
        boolean retiredNow, String contact, List<String> aliases, boolean clashing,
        String origin, List<RetirementFrom> pastRetirements, List<String> tags,
        List<SnapshotLine> snapshots, List<StatementSummary.Line> statements, String flag, String approver) {

    /** A snapshot's day being left (yyyy-MM-dd) and the due-total as it stood then (two decimals, or n/a). */
    public record SnapshotLine(String day, String dueTotal) {
    }

    /** A past retirement's from-date and to-date, the day they were unretired (yyyy-MM-dd). */
    public record RetirementFrom(String from, String to) {
    }

    /** A hold's from-date and to-date (yyyy-MM-dd; null for no end). */
    public record HoldFrom(String from, String to) {
    }

    /** A grade and the date it applies from (null for from the beginning of time). */
    public record GradeFrom(String grade, String from) {
    }

    public static PersonResponse from(Person p, LocalDate today, StatementSummary s, List<Long> patronIds,
            boolean clashing) {
        List<GradeFrom> grades = p.getGrades().entrySet().stream()
                .map(e -> new GradeFrom(e.getValue(), Person.START.equals(e.getKey()) ? null : e.getKey().toString()))
                .toList();
        return new PersonResponse(p.getId(), p.getName(), p.gradeOn(today), grades, p.getVersion(), s.count(),
                s.lastDueTotal(), s.lastDate(), p.isRetired(),
                p.getRetiredFrom() == null ? null : p.getRetiredFrom().toString(), p.isHeld(),
                p.getHolds().stream().map(h -> new HoldFrom(h.from().toString(), h.to() == null ? null : h.to().toString()))
                        .toList(),
                patronIds, p.termsOn(today), p.retiredOn(today), p.getContact(),
                List.copyOf(p.getAliases()), clashing, p.getOrigin(),
                p.getPastRetirements().stream().map(r -> new RetirementFrom(r.from().toString(), r.to().toString()))
                        .toList(),
                net.officefloor.hq.app.claim.Tags.list(p.getTags()),
                p.getSnapshots().stream().map(n -> new SnapshotLine(n.day().toString(), n.dueTotal())).toList(),
                s.lines(), p.flaggedOn(today) ? p.getFlag().reason() : null,
                p.getApprover());
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A hold on a person: from its from-date to its to-date (null: no end), both inclusive. */
public record Hold(LocalDate from, LocalDate to) {

    /** Whether the date falls within the hold. */
    public boolean covers(LocalDate date) {
        return !date.isBefore(from) && (to == null || !date.isAfter(to));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.InvalidSheetException;

/** The rule a retirement sets: no claim of a retired person dated after the date they are retired from, nor
 *  one dated after the from-date and before the to-date of a past retirement of theirs. */
public final class Retirement {
    private Retirement() {
    }

    public static void refuseClaimDate(Person person, LocalDate date) throws InvalidSheetException {
        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
            throw new InvalidSheetException(person.getName() + " is retired from " + person.getRetiredFrom());
        }
        for (PastRetirement past : person.getPastRetirements()) {
            if (past.bars(date)) {
                throw new InvalidSheetException(person.getName() + " was retired from " + past.from() + " to " + past.to());
            }
        }
    }
}

package net.officefloor.hq.app.person;

import java.sql.PreparedStatement;
import java.util.ArrayList;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import net.officefloor.hq.app.history.History;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people kept per sheet, in list order (by their position: a new person goes to the end, a move swaps
 *  two neighbours), each with their dated grades. */
@Repository
public class PersonStore {

    private final JdbcTemplate jdbc;

    public PersonStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The people's grades on the sheet (only the one person when {@code personId} is given), by person. */
    private Map<Long, NavigableMap<LocalDate, String>> grades(String sheetId, Long personId, String table) {
        Map<Long, NavigableMap<LocalDate, String>> grades = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, grade FROM " + table + " WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId), rs -> {
                    grades.computeIfAbsent(rs.getLong("person_id"), k -> new TreeMap<>())
                            .put(rs.getObject("from_date", LocalDate.class), rs.getString("grade"));
                }, sheetId);
        return grades;
    }

    /** The people's dated terms on the sheet (only the one person's when {@code personId} is given), by person. */
    private Map<Long, NavigableMap<LocalDate, Integer>> datedTerms(String sheetId, Long personId, String table) {
        Map<Long, NavigableMap<LocalDate, Integer>> terms = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, terms FROM " + table + " WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId), rs -> {
                    terms.computeIfAbsent(rs.getLong("person_id"), k -> new TreeMap<>())
                            .put(rs.getObject("from_date", LocalDate.class), rs.getObject("terms", Integer.class));
                }, sheetId);
        return terms;
    }

    /** The people's holds on the sheet (only the one person's when {@code personId} is given), by person, oldest first. */
    private Map<Long, List<Hold>> holds(String sheetId, Long personId, String table) {
        Map<Long, List<Hold>> holds = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM " + table + " WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId) + " ORDER BY id", rs -> {
                    holds.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(new Hold(
                            rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class)));
                }, sheetId);
        return holds;
    }

    /** The people's aliases on the sheet (only the one person's when {@code personId} is given), by person,
     *  sorted as names are compared. */
    private Map<Long, List<String>> aliases(String sheetId, Long personId, String table) {
        Map<Long, List<String>> aliases = new HashMap<>();
        jdbc.query("SELECT person_id, alias FROM " + table + " WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId) + " ORDER BY LOWER(alias), alias", rs -> {
                    aliases.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(rs.getString("alias"));
                }, sheetId);
        return aliases;
    }

    /** The people's past retirements on the sheet (only the one person's when {@code personId} is given), by
     *  person, oldest first. */
    private Map<Long, List<PastRetirement>> pastRetirements(String sheetId, Long personId, String table) {
        Map<Long, List<PastRetirement>> past = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM " + table + " WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId) + " ORDER BY id", rs -> {
                    past.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(new PastRetirement(
                            rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class)));
                }, sheetId);
        return past;
    }

    /** The people's snapshots on the sheet (only the one person's when {@code personId} is given), by person,
     *  oldest first. */
    private Map<Long, List<Snapshot>> snapshots(String sheetId, Long personId, String table) {
        Map<Long, List<Snapshot>> snapshots = new HashMap<>();
        jdbc.query("SELECT person_id, left_day, due_total FROM " + table + " WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId) + " ORDER BY id", rs -> {
                    snapshots.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(new Snapshot(
                            rs.getObject("left_day", LocalDate.class), rs.getString("due_total")));
                }, sheetId);
        return snapshots;
    }

    /** The people's flags on the sheet (only the one person's when {@code personId} is given), by person. */
    private Map<Long, Flag> flags(String sheetId, Long personId, String table) {
        Map<Long, Flag> flags = new HashMap<>();
        jdbc.query("SELECT person_id, reason, until_date FROM " + table + " WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId), rs -> {
                    flags.put(rs.getLong("person_id"),
                            new Flag(rs.getString("reason"), rs.getObject("until_date", LocalDate.class)));
                }, sheetId);
        return flags;
    }

    /** The people's approvers on the sheet (only the one person's when {@code personId} is given), by person. */
    private Map<Long, String> approvers(String sheetId, Long personId) {
        Map<Long, String> approvers = new HashMap<>();
        jdbc.query("SELECT person_id, approver FROM person_approver WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId), rs -> {
                    approvers.put(rs.getLong("person_id"), rs.getString("approver"));
                }, sheetId);
        return approvers;
    }

    private List<Person> query(String sheetId, Long personId, String sql, Object... args) {
        return queryFrom(sheetId, personId, "person_grade", "person_hold", "person_alias", "person_retirement",
                "person_snapshot", "person_terms", "person_flag", sql, args);
    }

    private List<Person> queryFrom(String sheetId, Long personId, String gradeTable, String holdTable,
            String aliasTable, String retirementTable, String snapshotTable, String termsTable, String flagTable, String sql,
            Object... args) {
        Map<Long, NavigableMap<LocalDate, Integer>> dated = datedTerms(sheetId, personId, termsTable);
        Map<Long, NavigableMap<LocalDate, String>> grades = grades(sheetId, personId, gradeTable);
        Map<Long, List<Hold>> holds = holds(sheetId, personId, holdTable);
        Map<Long, List<String>> aliases = aliases(sheetId, personId, aliasTable);
        Map<Long, List<PastRetirement>> past = pastRetirements(sheetId, personId, retirementTable);
        Map<Long, List<Snapshot>> snapshots = snapshots(sheetId, personId, snapshotTable);
        Map<Long, Flag> flags = flags(sheetId, personId, flagTable);
        Map<Long, String> approvers = approvers(sheetId, personId);
        RowMapper<Person> row = (rs, i) -> {
            Person p = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
                    grades.getOrDefault(rs.getLong("id"), new TreeMap<>()), rs.getLong("version"),
                    rs.getObject("retired_from", LocalDate.class), holds.getOrDefault(rs.getLong("id"), List.of()));
            p.setTerms(rs.getObject("terms", Integer.class));
            p.getDatedTerms().putAll(dated.getOrDefault(rs.getLong("id"), new TreeMap<>()));
            p.setContact(rs.getString("contact"));
            p.setTags(rs.getString("tags"));
            p.setOrigin(rs.getString("origin"));
            p.setArrivedOn(rs.getObject("arrived_on", LocalDate.class));
            p.setFlag(flags.get(rs.getLong("id")));
            p.setApprover(approvers.get(rs.getLong("id")));
            p.getAliases().addAll(aliases.getOrDefault(rs.getLong("id"), List.of()));
            p.getPastRetirements().addAll(past.getOrDefault(rs.getLong("id"), List.of()));
            p.getSnapshots().addAll(snapshots.getOrDefault(rs.getLong("id"), List.of()));
            return p;
        };
        return jdbc.query(sql, row, args);
    }

    public List<Person> list(String sheetId) {
        return query(sheetId, null, "SELECT * FROM person WHERE sheet_id = ? ORDER BY list_position, id", sheetId);
    }

    /** The people on the sheet as they stood at the end of the date, with their grades and holds then (see
     *  {@link History}), in list order then. */
    public List<Person> listAsOf(String sheetId, LocalDate date) {
        return queryFrom(sheetId, null, History.asOf("person_grade", "person_id, from_date", date),
                History.asOf("person_hold", "id", date), History.asOf("person_alias", "id", date),
                History.asOf("person_retirement", "id", date), History.asOf("person_snapshot", "id", date),
                History.asOf("person_terms", "person_id, from_date", date),
                History.asOf("person_flag", "sheet_id, person_id", date),
                "SELECT * FROM " + History.asOf("person", "id", date) + " WHERE sheet_id = ? ORDER BY list_position, id", sheetId);
    }

    public Person find(String sheetId, long id) {
        List<Person> found = query(sheetId, id, "SELECT * FROM person WHERE sheet_id = ? AND id = ?", sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person as they stood at the end of the date, with their grades and holds then (see {@link History});
     *  null when they were not on the sheet then. */
    public Person findAsOf(String sheetId, long id, LocalDate date) {
        List<Person> found = queryFrom(sheetId, id, History.asOf("person_grade", "person_id, from_date", date),
                History.asOf("person_hold", "id", date), History.asOf("person_alias", "id", date),
                History.asOf("person_retirement", "id", date), History.asOf("person_snapshot", "id", date),
                History.asOf("person_terms", "person_id, from_date", date),
                History.asOf("person_flag", "sheet_id, person_id", date),
                "SELECT * FROM " + History.asOf("person", "id", date) + " WHERE sheet_id = ? AND id = ?", sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person on the sheet with this name or alias, ignoring case and the spaces around it; null when none. */
    public Person findByName(String sheetId, String name) {
        List<Person> found = query(sheetId, null, "SELECT * FROM person WHERE sheet_id = ? AND (name_key = LOWER(?)"
                + " OR id IN (SELECT person_id FROM person_alias WHERE sheet_id = ? AND alias_key = LOWER(?)))",
                sheetId, name.trim(), sheetId, name.trim());
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether another person on the sheet (not {@code exceptId}) has this name, or anyone on the sheet has it
     *  as an alias, ignoring case. */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(?) AND id <> ?",
                Integer.class, sheetId, name.trim(), exceptId == null ? -1L : exceptId);
        return (n != null && n > 0) || aliasTaken(sheetId, name);
    }

    /** Whether anyone on any of the sheets has this name or alias, ignoring case and the spaces around it. */
    public boolean usedOn(List<String> sheetIds, String name) {
        for (String sheetId : sheetIds) {
            if (nameTaken(sheetId, name, null)) {
                return true;
            }
        }
        return false;
    }

    /** The names and aliases used on any of the sheets, lower-cased. */
    public java.util.Set<String> namesOn(List<String> sheetIds) {
        java.util.Set<String> names = new java.util.HashSet<>();
        for (String sheetId : sheetIds) {
            names.addAll(jdbc.queryForList("SELECT name_key FROM person WHERE sheet_id = ?", String.class, sheetId));
            names.addAll(jdbc.queryForList("SELECT alias_key FROM person_alias WHERE sheet_id = ?", String.class,
                    sheetId));
        }
        return names;
    }

    /** Whether the person's name or any of their aliases is among the names (lower-cased). */
    public static boolean clashes(Person person, java.util.Set<String> names) {
        if (names.contains(person.getName().trim().toLowerCase(java.util.Locale.ROOT))) {
            return true;
        }
        return person.getAliases().stream().anyMatch(a -> names.contains(a.trim().toLowerCase(java.util.Locale.ROOT)));
    }

    /** Whether anyone on the sheet has this alias, ignoring case and the spaces around it. */
    public boolean aliasTaken(String sheetId, String alias) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM person_alias WHERE sheet_id = ? AND alias_key = LOWER(?)",
                Integer.class, sheetId, alias.trim());
        return n != null && n > 0;
    }

    /** Adds the alias (trimmed) to the person's aliases. An edit of their name or grade leaves them as they are. */
    public void addAlias(Person person, String alias) {
        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", person.getSheetId(),
                person.getId(), alias.trim());
        person.getAliases().add(alias.trim());
        person.getAliases().sort(java.util.Comparator.comparing((String a) -> a.toLowerCase(java.util.Locale.ROOT))
                .thenComparing(java.util.Comparator.naturalOrder()));
    }

    /** Adds the person with their first grade, which applies from the beginning of time, and no terms of their own. */
    public Person add(String sheetId, String name, String grade) {
        return add(sheetId, name, grade, null);
    }

    /** Adds the person with their first grade, which applies from the beginning of time, and their own
     *  terms (null for none). */
    public Person add(String sheetId, String name, String grade, Integer terms) {
        return add(sheetId, name, grade, terms, null);
    }

    /** Whether another person on the sheet (not {@code exceptId}) has this contact (trimmed, lower-cased). */
    public boolean contactTaken(String sheetId, String contact, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND contact = ? AND id <> ?",
                Integer.class, sheetId, contact, exceptId == null ? -1L : exceptId);
        return n != null && n > 0;
    }

    /** Adds the person with their first grade, which applies from the beginning of time, their own
     *  terms (null for none) and their contact (null for none). */
    public Person add(String sheetId, String name, String grade, Integer terms, String contact) {
        return add(sheetId, name, grade, terms, contact, null);
    }

    /** Adds the person as {@link #add(String, String, String, Integer, String)} does, with their tags as stored
     *  (null for none). */
    public Person add(String sheetId, String name, String grade, Integer terms, String contact, String tags) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name, terms, contact, tags, list_position) VALUES (?, ?, ?, ?, ?, (SELECT"
                    + " COALESCE(MAX(list_position), 0) + 1 FROM person WHERE sheet_id = ?))", new String[] { "ID" });
            ps.setString(1, sheetId);
            ps.setString(2, name);
            ps.setObject(3, terms, java.sql.Types.INTEGER);
            ps.setString(4, contact);
            ps.setString(5, tags);
            ps.setString(6, sheetId);
            return ps;
        }, keys);
        long id = keys.getKey().longValue();
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)", sheetId,
                id, Person.START, grade);
        Person person = new Person(id, sheetId, name, new TreeMap<>(Map.of(Person.START, grade)), 0);
        person.setTerms(terms);
        person.setContact(contact);
        person.setTags(tags);
        return person;
    }

    /**
     * Stores the person over the version it was loaded at, moving the version on; false (nothing
     * stored) when someone else has stored another version since. The grade the edit records (if any)
     * is kept with the ones already recorded, replacing one from the same date.
     */
    public boolean save(Person person) {
        int n = jdbc.update(
                "UPDATE person SET name = ?, terms = ?, contact = ?, tags = ?, version = version + 1 WHERE sheet_id = ? AND id = ? AND version = ?",
                person.getName(), person.getTerms(), person.getContact(), person.getTags(), person.getSheetId(), person.getId(), person.getVersion());
        if (n == 1) {
            person.setVersion(person.getVersion() + 1);
            LocalDate from = person.getRecordFrom();
            if (from != null) {
                jdbc.update("MERGE INTO person_grade (sheet_id, person_id, from_date, grade) KEY (person_id, from_date)"
                        + " VALUES (?, ?, ?, ?)", person.getSheetId(), person.getId(), from, person.getGrades().get(from));
            }
            LocalDate termsFrom = person.getTermsRecordFrom();
            if (termsFrom != null) {
                recordTerms(person, termsFrom);
            }
        }
        return n == 1;
    }

    /** Makes every grade record of the person on {@code from} one of {@code into}, whatever its from-date (in the
     *  person too), keeping its from-date. */
    public void regrade(Person person, String from, String into) {
        jdbc.update("UPDATE person_grade SET grade = ? WHERE sheet_id = ? AND person_id = ? AND grade = ?", into,
                person.getSheetId(), person.getId(), from);
        person.getGrades().replaceAll((date, grade) -> grade.equals(from) ? into : grade);
    }

    /** Stores the person's dated terms from the date, replacing any from the same date. */
    public void recordTerms(Person person, LocalDate from) {
        jdbc.update("MERGE INTO person_terms (sheet_id, person_id, from_date, terms) KEY (person_id, from_date)"
                + " VALUES (?, ?, ?, ?)", person.getSheetId(), person.getId(), from, person.getDatedTerms().get(from));
    }

    /**
     * Swaps the person with their neighbour in the list (the one above when {@code up}, else the one below);
     * answers the person's new position in the list, counting from 1, or 0 (nothing stored) when there is no
     * neighbour that way: the top cannot move up, nor the bottom down. An edit of them leaves it as it is.
     */
    public int move(Person person, boolean up) {
        List<long[]> order = jdbc.query("SELECT id, list_position FROM person WHERE sheet_id = ? ORDER BY list_position, id"
                + " FOR UPDATE", (rs, i) -> new long[] { rs.getLong("id"), rs.getLong("list_position") },
                person.getSheetId());
        int at = -1;
        for (int i = 0; i < order.size(); i++) {
            if (order.get(i)[0] == person.getId()) {
                at = i;
            }
        }
        int to = up ? at - 1 : at + 1;
        if (at < 0 || to < 0 || to >= order.size()) {
            return 0;
        }
        long[] mine = order.get(at);
        long[] theirs = order.get(to);
        if (mine[1] == theirs[1]) {
            // tied positions (never made by this store): number them apart first, so the swap moves them
            renumber(person.getSheetId(), order);
            return move(person, up);
        }
        jdbc.update("UPDATE person SET list_position = ? WHERE sheet_id = ? AND id = ?", theirs[1], person.getSheetId(),
                mine[0]);
        jdbc.update("UPDATE person SET list_position = ? WHERE sheet_id = ? AND id = ?", mine[1], person.getSheetId(),
                theirs[0]);
        return to + 1;
    }

    /** Gives the people positions 1, 2, ... in their present order. */
    private void renumber(String sheetId, List<long[]> order) {
        for (int i = 0; i < order.size(); i++) {
            jdbc.update("UPDATE person SET list_position = ? WHERE sheet_id = ? AND id = ?", i + 1, sheetId, order.get(i)[0]);
        }
    }

    /** Retires the person from the date. An edit of their name or grade leaves it as it is. */
    public void retire(Person person, LocalDate from) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet_id = ? AND id = ?", from, person.getSheetId(),
                person.getId());
        person.setRetiredFrom(from);
    }

    /** Unretires the person on the date, keeping their retirement as a past one, from its date to this one. */
    public void unretire(Person person, LocalDate on) {
        jdbc.update("INSERT INTO person_retirement (sheet_id, person_id, from_date, to_date) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), person.getRetiredFrom(), on);
        jdbc.update("UPDATE person SET retired_from = NULL WHERE sheet_id = ? AND id = ?", person.getSheetId(),
                person.getId());
        person.getPastRetirements().add(new PastRetirement(person.getRetiredFrom(), on));
        person.setRetiredFrom(null);
    }

    /** Keeps a snapshot of the person on the sheet: the day being left and their due-total as it stood then. */
    public void snapshot(String sheetId, long personId, LocalDate day, String dueTotal) {
        jdbc.update("INSERT INTO person_snapshot (sheet_id, person_id, left_day, due_total) VALUES (?, ?, ?, ?)",
                sheetId, personId, day, dueTotal);
    }

    /** Adds a hold to the person's holds. An edit of their name or grade leaves them as they are. */
    public void hold(Person person, Hold hold) {
        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), hold.from(), hold.to());
        person.addHold(hold);
    }

    /** Puts the flag on the person, replacing any they had. */
    public void flag(Person person, Flag flag) {
        jdbc.update("MERGE INTO person_flag (sheet_id, person_id, reason, until_date) KEY (sheet_id, person_id) "
                + "VALUES (?, ?, ?, ?)", person.getSheetId(), person.getId(), flag.reason(), flag.until());
        person.setFlag(flag);
    }

    /** Makes the user the person's approver, replacing any they had; a blank user clears it. */
    public void approver(Person person, String user) {
        if (user.isEmpty()) {
            jdbc.update("DELETE FROM person_approver WHERE sheet_id = ? AND person_id = ?", person.getSheetId(),
                    person.getId());
            person.setApprover(null);
        } else {
            jdbc.update("MERGE INTO person_approver (sheet_id, person_id, approver) KEY (sheet_id, person_id) "
                    + "VALUES (?, ?, ?)", person.getSheetId(), person.getId(), user);
            person.setApprover(user);
        }
    }

    /** Adds a copy of the person to the other sheet: their name, every grade with its from-date, their terms,
     *  contact, tags and aliases, noting this sheet as the one they came from. Their holds, statements and watchers
     *  are not carried (a transfer gives them their statements, see StatementStore). {@code arrivedOn} is the other
     *  sheet's today, the day they arrived there. */
    public Person copyTo(Person person, String toSheet, LocalDate arrivedOn) {
        Person copy = add(toSheet, person.getName(), person.gradeOn(Person.START), person.getTerms(), person.getContact(),
                person.getTags());
        person.getGrades().forEach((from, grade) -> {
            if (!from.equals(Person.START)) {
                jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)",
                        toSheet, copy.getId(), from, grade);
            }
        });
        person.getDatedTerms().forEach((from, terms) -> jdbc.update(
                "INSERT INTO person_terms (sheet_id, person_id, from_date, terms) VALUES (?, ?, ?, ?)", toSheet,
                copy.getId(), from, terms));
        for (String alias : person.getAliases()) {
            addAlias(copy, alias);
        }
        jdbc.update("UPDATE person SET origin = ?, arrived_on = ? WHERE sheet_id = ? AND id = ?", person.getSheetId(),
                arrivedOn, toSheet, copy.getId());
        return find(toSheet, copy.getId());
    }

    /** Drops the person from their sheet with their grades, holds, aliases, snapshots, statements and watchers. Their claims,
     *  patrons and pool memberships are dropped before this (see ClaimStore, PatronStore and PoolStore). */
    public void remove(Person person) {
        String sheetId = person.getSheetId();
        jdbc.update("DELETE FROM person_alias WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_terms WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_flag WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_approver WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_retirement WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_snapshot WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM statement WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM watch WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
    }

    /** Makes the person's name and aliases aliases of {@code into}, then drops the person with their grades,
     *  holds, snapshots, statements and watchers (their contact goes with them). Their claims, patrons and pool
     *  memberships are moved before this (see ClaimStore, PatronStore and PoolStore). */
    public void mergeInto(Person person, Person into) {
        String sheetId = person.getSheetId();
        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet_id = ? AND person_id = ?", into.getId(), sheetId,
                person.getId());
        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, person.getId());
        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", sheetId, into.getId(),
                person.getName());
        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_terms WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_flag WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_approver WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_retirement WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM person_snapshot WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM statement WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
        jdbc.update("DELETE FROM watch WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
    }
}
