  const fig = useFigure();
  const [sheet] = useCurrentSheet();
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  return (
    <p>
      Claimed total <strong data-testid="rollup-claimed-total">{fig(claimed(liveClaimed(claims.data ?? [], people.data)))}</strong>
    </p>
  );
}

